#ifndef SQLITEXX_CONFIG_HPP
#define SQLITEXX_CONFIG_HPP

// Build configuration and vocabulary types.
//
// Every public header gets its vocabulary types (string_view, and later span and expected) from here, never from
// std:: directly. When C++11/14 support arrives, this header becomes generated by CMake so the choice between the
// std type and its backport is fixed once per build instead of per translation unit (which would break the ODR).

#if defined(_MSVC_LANG)
#define SQLITEXX_CPLUSPLUS _MSVC_LANG
#else
#define SQLITEXX_CPLUSPLUS __cplusplus
#endif

#if SQLITEXX_CPLUSPLUS < 201703L
#error "sqlitexx currently needs C++17 or newer (C++11 and C++14 support is planned)"
#endif

#include <string_view>

namespace sqlitexx
{
using std::string_view;
using std::u16string_view;
} // sqlitexx

#endif // SQLITEXX_CONFIG_HPP
